mapper.select:
        SELECT DISTINCT a.id AS value,a.index_name AS label
		FROM system_docking.api_platform_index_info a
        LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id = b.id
        LEFT JOIN system_docking.api_interface_system_info c ON b.system_id = c.id
        WHERE a.is_monitor = '1' AND a.is_enable = '1' AND b.is_enable = '1' AND c.is_enable = '1'

            AND c.system_code=#{params.system_code}


            AND b.id=#{params.platform}


            AND a.index_type=#{params.index_type}

SELECT DISTINCT a.id AS value,a.platfrom_name AS label FROM system_docking.api_interface_system_platform_info a LEFT JOIN system_docking.api_interface_system_info b ON a.system_id = b.id WHERE a.is_enable = '1' AND b.is_enable = '1'
AND b.system_code=#{params.system_code}
AND EXISTS (SELECT DISTINCT c.platform_id FROM system_docking.api_platform_index_info c WHERE c.is_enable='1' AND c.is_monitor='${params.is_monitor}' AND a.ID=c.platform_id)
